{
  "title": "tBreg Breast Cancer Game",
  "perWatchSecond": 1,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "Hook: NK killing rate",
      "goal": "Show that even strong NK activity cannot stop tumor when tBregs are present.",
      "control": {
        "parameter": "c",
        "label": "NK killing rate",
        "lowEnd": "1e-10 (half)",
        "highEnd": "4e-10 (double)"
      },
      "watch": "tumor cell count (t)",
      "whatIf": {
        "prompt": "What if the NK killing rate is halved?",
        "parameter": "c",
        "value": 1e-10
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "higher",
        "by": 3000
      },
      "effect": "Halving the NK killing rate raises the tumor peak from about 99 to about 3380 cells, higher by more than 3000.",
      "prediction": {
        "prompt": "Predict the tumor peak after halving NK killing.",
        "claimed": "Higher",
        "other": "Lower"
      },
      "passage": {
        "title": "Finding 0",
        "quote": "a sufficiently large number of tBregs can cause the breast tumour to reach its carrying capacity, regardless of the rate of NK-induced breast cancer cell death."
      },
      "carryForward": "Next we vary the tumour growth rate a."
    },
    {
      "kind": "background",
      "finding": 2,
      "title": "Growth rate effect",
      "goal": "Demonstrate how tumour intrinsic growth influences size when tBregs are absent.",
      "control": {
        "parameter": "a",
        "label": "Tumour growth rate",
        "lowEnd": "0.075 (half)",
        "highEnd": "0.3 (double)"
      },
      "watch": "tumor cell count (t)",
      "whatIf": {
        "prompt": "What if the tumour growth rate is doubled?",
        "parameter": "a",
        "value": 0.3
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "higher",
        "by": 2280000
      },
      "effect": "Doubling the tumour growth rate raises the tumor peak to about 2.28 million cells, higher by more than 2 million.",
      "prediction": {
        "prompt": "Will the tumour become much larger?",
        "claimed": "Higher",
        "other": "Lower"
      },
      "passage": {
        "title": "Finding 2",
        "quote": "when tBregs do not exist in the body, the only way for the breast tumour to reach its carrying capacity is for the rate of NK-induced breast cancer cell death to be tending to 0"
      },
      "carryForward": "Now we examine the impact of NK cell death rate thetaN."
    },
    {
      "kind": "idea",
      "finding": 4,
      "title": "NK death threshold",
      "goal": "Explore the bifurcation caused by changing NK cell death rate.",
      "control": {
        "parameter": "thetaN",
        "label": "NK death rate",
        "lowEnd": "0.035 (half)",
        "highEnd": "0.14 (double)"
      },
      "watch": "tumor cell count (t)",
      "whatIf": {
        "prompt": "What if the NK death rate is doubled?",
        "parameter": "thetaN",
        "value": 0.14
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "higher",
        "by": 1400
      },
      "effect": "Doubling NK death rate raises the tumor peak to about 1530 cells, higher by more than 1400.",
      "prediction": {
        "prompt": "Will the tumour grow more with higher NK death?",
        "claimed": "Higher",
        "other": "Lower"
      },
      "passage": {
        "title": "Finding 4",
        "quote": "System [reducedModel] experiences a transcritical bifurcation at the equilibrium point E1 ≡ E2 as the parameter c varies through c1."
      },
      "carryForward": "We then test how the constant NK source sigma changes outcomes."
    },
    {
      "kind": "method",
      "finding": 5,
      "title": "NK source boost",
      "goal": "Show that increasing NK cell influx can suppress tumour despite tBregs.",
      "control": {
        "parameter": "sigma",
        "label": "NK source",
        "lowEnd": "2.5e7 (half)",
        "highEnd": "1e8 (double)"
      },
      "watch": "tumor cell count (t)",
      "whatIf": {
        "prompt": "What if the NK source is doubled?",
        "parameter": "sigma",
        "value": 100000000
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 90
      },
      "effect": "Doubling NK source reduces the tumor peak to about 5.7 cells, lower by more than 90.",
      "prediction": {
        "prompt": "Will the tumour shrink with more NK cells?",
        "claimed": "Lower",
        "other": "Higher"
      },
      "passage": {
        "title": "Finding 5",
        "quote": "when θB/mT > 1/b, our model has no closed orbits, meaning that breast cancer will either be cleared by NK cells or stabilise around a constant number."
      },
      "carryForward": "Finally we vary the Treg source kappa."
    },
    {
      "kind": "result",
      "finding": 3,
      "title": "Treg source effect",
      "goal": "Illustrate how increasing Treg influx shifts the system to a tumour‑present equilibrium.",
      "control": {
        "parameter": "kappa",
        "label": "Treg source",
        "lowEnd": "5e6 (half)",
        "highEnd": "2e7 (double)"
      },
      "watch": "tumor cell count (t)",
      "whatIf": {
        "prompt": "What if the Treg source is doubled?",
        "parameter": "kappa",
        "value": 20000000
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "higher",
        "by": 130
      },
      "effect": "Doubling Treg source raises the tumor peak to about 231 cells, higher by more than 130.",
      "prediction": {
        "prompt": "Will the tumour increase with more Tregs?",
        "claimed": "Higher",
        "other": "Lower"
      },
      "passage": {
        "title": "Finding 3",
        "quote": "We showed the existence of three biologically realistic equilibria: an equilibrium with no cancer cells, an equilibrium with cancer cells and no tBregs, and an equilibrium with both cancer cells and tBregs."
      },
      "carryForward": "The game ends with a reflection on the three possible outcomes."
    }
  ],
  "limits": [
    "All control parameters are rate constants.",
    "What‑If changes are halved or doubled as discussed in the paper."
  ]
}
